primaryQuery:
run: order_items extend {
  join_one: inventory_items is inventory_items
    on inventory_item_id = inventory_items.id
} -> {
  top: 5
  group_by: inventory_items.product_category
  aggregate: total_sales is sale_price.sum()
}

verifyQuery:
run: order_items extend {
  join_one: inventory_items on inventory_item_id = inventory_items.id
  join_one: products on inventory_items.product_id = products.id
} -> {
  top: 5
  group_by: product_category is products.category
  aggregate: total_sales is sale_price.sum()
  order_by: total_sales desc
  calculate: rank is row_number()
}
